export default {async fetch(request,env){
 const url=new URL(request.url);
 if(url.pathname==='/api/enquiries'){
  if(request.method!=='POST')return new Response('Method not allowed',{status:405});
  if(!env.API_ORIGIN)return Response.json({error:'Enquiry email service is not configured.'},{status:503});
  const target=new URL(env.API_ORIGIN);
  if(target.protocol!=='https:')return new Response('Invalid API origin',{status:503});
  target.pathname='/api/enquiries';target.search=url.search;
  return fetch(new Request(target,request));
 }
 if(url.pathname.startsWith('/api/'))return Response.json({error:'API route not found'},{status:404});
 if(!['GET','HEAD'].includes(request.method))return new Response('Method not allowed',{status:405});
 const asset=assets[url.pathname==='/'?'/index.html':url.pathname];if(!asset)return new Response('Not found',{status:404});
 return new Response(request.method==='HEAD'?null:Uint8Array.from(atob(asset.body),c=>c.charCodeAt(0)),{headers:{'Content-Type':asset.type,'X-Content-Type-Options':'nosniff'}});
}};
